        for i in range(len(ps)-1):
            (r0,c0),(r1,c1)=ps[i],ps[i+1]
            for dr,dc in ((1,-1),(1,1),(-1,-1),(-1,1)):
                if r1==r0+dr and c1==c0+dc:
                    # try extending forward from second cell; if blocked, try backward from first
                    r,c=r1+dr,c1+dc; ok=True
                    while 0<=r<H and 0<=c<W:
                        if g[r][c]!=bg: ok=False; break
                        r+=dr; c+=dc
                    if ok:
